// CHIMICA — risposta multipla (parte 2: organica e biomolecole) + completamento
BANK.push(
{id:"C080",s:"chem",u:6,q:"Nel propene (CH₂=CH−CH₃) gli atomi di carbonio hanno ibridazione, nell'ordine:",o:["sp², sp², sp³","sp³, sp³, sp³","sp, sp, sp³","sp², sp³, sp³","sp, sp², sp³"],e:"I due carboni del doppio legame sono sp²; il metile è sp³.",h:"I carboni del doppio legame sono sp², quelli con soli legami semplici sp³.",x:"Il propene ha un doppio legame, quindi non sono tutti sp³; non c'è un triplo legame, quindi nessun carbonio è sp; il secondo carbonio partecipa al doppio legame ed è sp²."},
{id:"C081",s:"chem",u:6,q:"La formula molecolare generale degli alcani aciclici è:",o:["CₙH₂ₙ₊₂","CₙH₂ₙ","CₙH₂ₙ₋₂","CₙHₙ","CₙH₂ₙ₊₁OH"],e:"CₙH₂ₙ è la formula di alcheni e cicloalcani; CₙH₂ₙ₋₂ quella degli alchini e dei dieni.",h:"Per ogni carbonio ci sono 2 H, più 2 H alle estremità della catena.",x:"CₙH₂ₙ sono alcheni e cicloalcani; CₙH₂ₙ₋₂ alchini e dieni; CₙHₙ ricorda il benzene; CₙH₂ₙ₊₁OH sono gli alcoli."},
{id:"C082",s:"chem",u:6,q:"Il nome IUPAC del composto CH₃−CH(CH₃)−CH₂−CH₃ è:",o:["2-metilbutano","3-metilbutano","isopentano normale","2-etilpropano","pentano"],e:"La catena più lunga ha 4 carboni (butano), con un metile sul C2: la numerazione va scelta in modo da dare ai sostituenti il numero più basso.",h:"Trova la catena più lunga (4 C) e numera dando il numero più basso al sostituente.",x:"3-metilbutano numera dal lato sbagliato; 'isopentano normale' non è un nome IUPAC; 2-etilpropano non usa la catena più lunga; pentano è il composto lineare (isomero)."},
{id:"C083",s:"chem",u:6,q:"La reazione tipica degli alcani con il cloro in presenza di luce UV è:",o:["sostituzione radicalica","addizione elettrofila","sostituzione nucleofila","eliminazione","sostituzione elettrofila aromatica"],e:"La luce rompe omoliticamente Cl₂; i radicali Cl· sottraggono un H all'alcano in una reazione a catena.",h:"La luce UV rompe Cl₂ in due radicali Cl·, che strappano un H all'alcano.",x:"Gli alcani non hanno doppi legami (niente addizione), non hanno gruppi uscenti per una SN né anelli aromatici; non si eliminano piccole molecole."},
{id:"C084",s:"chem",u:6,q:"L'addizione di HBr al propene, secondo la regola di Markovnikov, dà come prodotto principale:",o:["2-bromopropano","1-bromopropano","1,2-dibromopropano","propano","bromuro di allile"],e:"L'H⁺ si lega al carbonio che ha più idrogeni, formando il carbocatione secondario, più stabile; Br⁻ si lega poi al C2.",h:"Markovnikov: l'H⁺ va sul carbonio con più idrogeni, e il bromo su quello più sostituito.",x:"1-bromopropano è il prodotto anti-Markovnikov; il dibromuro richiederebbe Br₂; il propano si ottiene con H₂; il bromuro di allile è una sostituzione."},
{id:"C085",s:"chem",u:6,q:"L'ordine di stabilità dei carbocationi è:",o:["terziario > secondario > primario > metilico","metilico > primario > secondario > terziario","primario > secondario > terziario","secondario > terziario > primario","tutti hanno la stessa stabilità"],e:"I gruppi alchilici donano densità elettronica (effetto induttivo e iperconiugazione) e stabilizzano la carica positiva.",h:"I gruppi alchilici donano densità elettronica e stabilizzano la carica positiva.",x:"Più gruppi alchilici significa più stabilità, quindi l'ordine non può essere inverso; il secondario non è più stabile del terziario; le stabilità sono diverse."},
{id:"C086",s:"chem",u:6,q:"Una reazione SN2:",o:["avviene in un solo stadio con inversione di configurazione","avviene in un solo stadio con ritenzione di configurazione","passa attraverso un carbocatione e porta a racemizzazione","è favorita sui substrati terziari e nei solventi protici","ha velocità che dipende solo dalla concentrazione del substrato"],e:"Il nucleofilo attacca dal lato opposto al gruppo uscente (inversione di Walden); v = k[substrato][nucleofilo]; è favorita sui substrati metilici e primari.",h:"Il nucleofilo attacca dal lato opposto al gruppo uscente, in un solo passaggio.",x:"L'attacco dal retro inverte la configurazione (non la ritiene); il carbocatione e la racemizzazione sono tipici della SN1; i substrati terziari favoriscono la SN1; la velocità dipende anche dal nucleofilo."},
{id:"C087",s:"chem",u:6,q:"Una reazione SN1 è favorita da:",o:["substrati terziari e solventi polari protici","substrati primari e solventi polari aprotici","nucleofili forti in alta concentrazione","substrati metilici e solventi apolari","substrati terziari e solventi apolari"],e:"Lo stadio lento è la formazione del carbocatione, stabilizzato dalla sostituzione e dal solvente polare protico; v = k[substrato].",h:"Lo stadio lento è la formazione del carbocatione: cosa lo stabilizza?",x:"Substrati primari e metilici formano carbocationi instabili (SN2); i nucleofili forti favoriscono la SN2; i solventi apolari non stabilizzano gli ioni."},
{id:"C088",s:"chem",u:6,q:"Secondo la regola di Hückel, un composto ciclico planare e completamente coniugato è aromatico se possiede:",o:["4n + 2 elettroni π","4n elettroni π","un numero dispari di atomi di carbonio","solo legami semplici","almeno un eteroatomo"],e:"Il benzene ha 6 elettroni π (n = 1). I sistemi con 4n elettroni π sono antiaromatici.",h:"Il benzene ha 6 elettroni π: 6 = 4n + 2 con n = 1.",x:"4n elettroni π danno sistemi antiaromatici; il numero di carboni, i legami semplici e gli eteroatomi non definiscono l'aromaticità."},
{id:"C089",s:"chem",u:6,q:"La reazione tipica del benzene è:",o:["la sostituzione elettrofila aromatica","l'addizione elettrofila al doppio legame","la sostituzione nucleofila aromatica","l'addizione nucleofila all'anello","la sostituzione radicalica sull'anello"],e:"La sostituzione conserva l'anello aromatico stabile; l'addizione distruggerebbe l'aromaticità.",h:"Il benzene preferisce reazioni che conservano l'anello aromatico stabile.",x:"Un'addizione distruggerebbe l'aromaticità; l'anello è ricco di elettroni, quindi reagisce con elettrofili e non con nucleofili; la sostituzione radicalica non è tipica dell'anello."},
{id:"C090",s:"chem",u:6,q:"Nella sostituzione elettrofila aromatica, il gruppo −NO₂ legato all'anello è:",o:["disattivante e orientante in meta","attivante e orientante in orto/para","attivante e orientante in meta","disattivante e orientante in orto/para","senza effetto"],e:"Il nitro è un forte elettron-attrattore. Gruppi come −OH, −NH₂ e −CH₃ sono invece attivanti e orto/para orientanti; gli alogeni sono disattivanti ma orto/para orientanti.",h:"Il gruppo nitro è un forte elettron-attrattore.",x:"Un elettron-attrattore toglie densità all'anello: non può essere attivante. I disattivanti forti (esclusi gli alogeni) orientano in meta; un effetto c'è sempre."},
{id:"C091",s:"chem",u:6,q:"Il benzene è considerato tossico soprattutto perché:",o:["è cancerogeno e tossico per il midollo osseo","è un acido forte che corrode le mucose","è radioattivo a causa del carbonio-14","provoca solo irritazione cutanea reversibile","è un gas asfissiante che sposta l'ossigeno"],e:"I metaboliti epatici del benzene danneggiano il midollo osseo; è classificato come cancerogeno certo per l'uomo (IARC gruppo 1).",h:"È un cancerogeno certo per l'uomo (IARC gruppo 1) e danneggia la produzione di cellule del sangue.",x:"Il benzene non è un acido né radioattivo; non è un semplice irritante reversibile; è un liquido, non un gas asfissiante."},
{id:"C092",s:"chem",u:6,q:"Un nucleofilo è una specie che:",o:["dona un doppietto elettronico a un centro povero di elettroni","accetta un doppietto elettronico da un centro ricco di elettroni","dona un doppietto elettronico a un centro ricco di elettroni","è sempre un catione con un orbitale vuoto","è necessariamente un radicale con un elettrone spaiato"],e:"Esempi di nucleofili: OH⁻, NH₃, H₂O, CN⁻. Gli elettrofili (es. H⁺, carbocationi) accettano doppietti.",h:"'Nucleo-filo' = amante del nucleo (di cariche positive): cerca centri poveri di elettroni.",x:"Accettare doppietti è la definizione di elettrofilo; un nucleofilo non cerca centri ricchi di elettroni; non è un catione con orbitale vuoto né necessariamente un radicale."},
{id:"C093",s:"chem",u:6,q:"La rottura eterolitica di un legame covalente produce:",o:["due ioni di carica opposta","due radicali","due atomi neutri con un elettrone spaiato ciascuno","una molecola apolare","nessuna specie reattiva"],e:"Nella rottura eterolitica entrambi gli elettroni restano su un frammento (anione), l'altro rimane positivo. Nell'omolitica ogni frammento tiene un elettrone (radicali).",h:"'Etero' = diverso: i due elettroni del legame vanno entrambi sullo stesso frammento.",x:"Due radicali (o atomi con un elettrone spaiato) sono il risultato della rottura omolitica; si formano specie cariche e reattive, non una molecola apolare."},
{id:"C094",s:"chem",u:6,q:"Il cicloesano è stabile e privo di tensione d'anello soprattutto perché:",o:["assume la conformazione a sedia con angoli di circa 109,5°","assume una conformazione planare con angoli di legame di 120°","assume la conformazione a barca con angoli di 90°","contiene doppi legami coniugati che lo stabilizzano","ha carboni sp² come il benzene"],e:"Nella conformazione a sedia gli angoli sono tetraedrici e gli idrogeni sfalsati. Il ciclopropano ha invece una forte tensione d'anello (angoli di 60°).",h:"Nella conformazione a sedia gli angoli sono vicini a quelli tetraedrici dei carboni sp³.",x:"Un anello planare avrebbe angoli di 120°, troppo grandi per sp³; la barca è meno stabile; il cicloesano non ha doppi legami né carboni sp²."},

{id:"C095",s:"chem",u:7,q:"L'ossidazione di un alcol primario con un ossidante blando produce:",o:["un'aldeide","un chetone","un etere","un estere","un alcano"],e:"Alcol primario → aldeide → (ossidante forte) acido carbossilico. Alcol secondario → chetone. Alcol terziario: non si ossida in condizioni blande.",h:"Alcol primario → aldeide → acido carbossilico, man mano che l'ossidazione procede.",x:"Il chetone si ottiene da un alcol secondario; eteri ed esteri non si formano per ossidazione di un alcol; un alcano è più ridotto dell'alcol."},
{id:"C096",s:"chem",u:7,q:"L'ossidazione dell'etanolo nel fegato (alcol deidrogenasi) produce:",o:["acetaldeide","acetone","metanolo","acido formico","glicole etilenico"],e:"L'acetaldeide, tossica, viene poi ossidata ad acetato dall'aldeide deidrogenasi.",h:"L'etanolo è un alcol primario: la prima ossidazione dà l'aldeide corrispondente a due carboni.",x:"L'acetone deriva dal 2-propanolo; metanolo e acido formico hanno un solo carbonio; il glicole etilenico è un diolo, non un prodotto di ossidazione."},
{id:"C097",s:"chem",u:7,q:"Il fenolo è più acido dell'etanolo perché:",o:["la carica dello ione fenato è delocalizzata per risonanza sull'anello","l'ossidrile del fenolo forma legami a idrogeno più forti","l'anello aromatico dona elettroni all'ossigeno e lo stabilizza","il fenolo è un acido forte completamente dissociato","l'etanolo ha una base coniugata stabilizzata per risonanza"],e:"Il pKa del fenolo è circa 10, quello dell'etanolo circa 16: la stabilizzazione per risonanza della base coniugata rende il fenolo più acido.",h:"Un acido è più forte quanto più è stabile la sua base coniugata.",x:"I legami a idrogeno non spiegano l'acidità; l'anello attrae (non dona) la carica negativa per risonanza; il fenolo è un acido debole; l'etossido non ha risonanza."},
{id:"C098",s:"chem",u:7,q:"L'addizione di un alcol al gruppo carbonilico di un'aldeide forma:",o:["un emiacetale","un estere","un etere","un acetale","un chetale"],e:"Aldeide + alcol ⇌ emiacetale; con un secondo alcol, in ambiente acido, si forma un acetale. La ciclizzazione del glucosio è un emiacetale intramolecolare.",h:"Il primo prodotto dell'addizione di un alcol a un'aldeide ha un −OH e un −OR sullo stesso carbonio.",x:"Esteri ed eteri si formano con altre reazioni; l'acetale richiede un secondo alcol; chetali ed emichetali derivano dai chetoni."},
{id:"C099",s:"chem",u:7,q:"La tautomeria cheto-enolica è un equilibrio tra:",o:["un carbonile e il suo enolo, per spostamento di un H in α","un'aldeide e un chetone con lo stesso numero di carboni","un alcol e un etere con la stessa formula bruta","due enantiomeri che si interconvertono","un carbonile e il suo enolo, per spostamento di un H in β"],e:"L'idrogeno in α al carbonile è debolmente acido; l'equilibrio è importante in reazioni biologiche come l'isomerizzazione dei fosfati di zuccheri in glicolisi.",h:"Nella tautomeria si sposta un H dal carbonio adiacente al carbonile (posizione α) all'ossigeno.",x:"Aldeide e chetone non sono tautomeri; alcol ed etere sono isomeri di funzione; gli enantiomeri non sono tautomeri; l'H coinvolto è in α, non in β."},
{id:"C100",s:"chem",u:7,q:"La condensazione aldolica forma un nuovo legame:",o:["C−C tra un enolato e il carbonio carbonilico di un altro carbonile","C−O tra un enolato e l'ossigeno carbonilico di un altro carbonile","C−N tra un'ammina e il carbonio carbonilico di un'aldeide","C−C tra due carbonili con eliminazione di CO₂","estere tra un acido carbossilico e un alcol"],e:"Il prodotto è un β-idrossicarbonile. In biochimica, l'aldolasi della glicolisi catalizza la reazione inversa.",h:"L'enolato (nucleofilo al carbonio) attacca il carbonio carbonilico di un'altra molecola.",x:"Si forma un legame carbonio-carbonio, non C−O né C−N; non si elimina CO₂; non si forma un estere."},
{id:"C101",s:"chem",u:7,q:"La reazione tra un acido carbossilico e un alcol in ambiente acido (esterificazione di Fischer) produce:",o:["un estere e acqua","un'ammide e acqua","un etere e acqua","un'anidride","un sale"],e:"R−COOH + R'−OH ⇌ R−COO−R' + H₂O. La reazione è reversibile; l'idrolisi basica degli esteri si chiama saponificazione.",h:"Esterificazione: l'OH dell'acido e l'H dell'alcol escono come acqua.",x:"Un'ammide richiede un'ammina; un etere si forma da due alcoli; un'anidride da due acidi; un sale da acido e base."},
{id:"C102",s:"chem",u:7,q:"Tra i derivati degli acidi carbossilici, il più reattivo nella sostituzione nucleofila acilica è:",o:["il cloruro acilico","l'ammide","l'estere","l'acido carbossilico","il carbossilato"],e:"Ordine di reattività: alogenuri acilici > anidridi > tioesteri > esteri > ammidi. I tioesteri (es. acetil-CoA) sono intermedi 'attivati' in biochimica.",h:"Il derivato più reattivo è quello con il miglior gruppo uscente legato al carbonile.",x:"Ammidi ed esteri hanno gruppi uscenti scarsi (NH₂⁻, RO⁻); l'acido ha OH⁻; il carbossilato è carico negativamente e poco attaccabile. Cl⁻ è un ottimo gruppo uscente."},
{id:"C103",s:"chem",u:7,q:"Le ammine si comportano da basi perché:",o:["l'azoto ha un doppietto solitario che può accettare un protone","l'azoto cede facilmente all'acqua il protone legato","l'azoto ha un orbitale vuoto che accetta un doppietto dall'acqua","l'anello aromatico dona elettroni all'azoto","contengono un gruppo carbossilico deprotonato"],e:"Le ammine alifatiche sono basi un po' più forti dell'ammoniaca; quelle aromatiche (anilina) sono più deboli per la delocalizzazione del doppietto sull'anello.",h:"Come l'ammoniaca, l'azoto delle ammine ha un doppietto libero.",x:"Le ammine non cedono protoni (non sono acidi); un orbitale vuoto descrive un acido di Lewis; l'anello aromatico riduce, non aumenta, la basicità; le ammine non hanno carbossili."},
{id:"C104",s:"chem",u:7,q:"Le ammidi, rispetto alle ammine, sono:",o:["quasi non basiche: il doppietto dell'azoto è delocalizzato sul carbonile","basi più forti: il carbonile aumenta la densità elettronica sull'azoto","acidi forti: il carbonile rende l'N−H completamente dissociato","basi simili: il carbonile non influenza il doppietto","quasi non basiche perché l'azoto non ha doppietti solitari"],e:"La risonanza conferisce al legame C−N un parziale carattere di doppio legame: è il motivo per cui il legame peptidico è planare e rigido.",h:"Il doppietto dell'azoto ammidico è delocalizzato sul C=O per risonanza.",x:"Il carbonile sottrae (non aumenta) densità elettronica all'azoto; le ammidi non sono acidi forti; l'azoto ha un doppietto, ma non è disponibile."},
{id:"C105",s:"chem",u:7,q:"Una base di Schiff (immina) si forma dalla reazione tra:",o:["un'aldeide o un chetone e un'ammina primaria","un'aldeide o un chetone e un'ammina terziaria","un acido carbossilico e un'ammina primaria","un'aldeide e un alcol in ambiente acido","un estere e un'ammina secondaria"],e:"Si forma un doppio legame C=N con eliminazione di acqua. Esempi biologici: il legame retinale-opsina nella rodopsina e gli intermedi con il piridossal fosfato.",h:"Si forma un doppio legame C=N con eliminazione di acqua: all'azoto servono due H da perdere.",x:"Un'ammina terziaria non ha H sull'azoto; acido + ammina dà un'ammide; aldeide + alcol dà emiacetali e acetali; estere + ammina dà ammidi."},
{id:"C106",s:"chem",u:7,q:"L'urea è chimicamente:",o:["la diammide dell'acido carbonico","l'ammide dell'acido acetico","un amminoacido a due atomi di azoto","il diestere dell'acido carbonico","un'ammina terziaria"],e:"Formula H₂N−CO−NH₂: è la principale forma di eliminazione dell'azoto nei mammiferi.",h:"Formula H₂N−CO−NH₂: un carbonile con due gruppi amminici.",x:"Non ha uno scheletro acetico né un gruppo carbossilico (non è un amminoacido); non contiene esteri; i suoi azoti sono ammidici, non terziari."},
{id:"C107",s:"chem",u:7,q:"Due molecole sono enantiomeri quando:",o:["sono immagini speculari non sovrapponibili","hanno diversa formula molecolare","differiscono per la posizione di un doppio legame","sono immagini speculari sovrapponibili","differiscono per la configurazione di uno solo di più centri stereogenici"],e:"Gli enantiomeri hanno le stesse proprietà fisiche ma ruotano la luce polarizzata in senso opposto. Gli epimeri, citati tra le opzioni, sono invece un tipo di diastereoisomeri.",h:"Come la mano destra e la sinistra: speculari ma non sovrapponibili.",x:"Gli enantiomeri hanno la stessa formula; la posizione di un doppio legame riguarda gli isomeri costituzionali; se fossero sovrapponibili sarebbero la stessa molecola; un solo centro diverso descrive gli epimeri."},
{id:"C108",s:"chem",u:7,q:"Una miscela racemica:",o:["contiene quantità uguali di due enantiomeri ed è otticamente inattiva","contiene quantità uguali di due diastereoisomeri ed è otticamente attiva","contiene un solo enantiomero e ruota il piano della luce polarizzata","è un composto meso con due centri chirali opposti","contiene quantità diverse di due enantiomeri ed è inattiva"],e:"Le rotazioni opposte dei due enantiomeri si annullano.",h:"Le rotazioni opposte dei due enantiomeri si annullano se sono in quantità uguali.",x:"Con diastereoisomeri o quantità diverse le rotazioni non si annullano; un solo enantiomero è otticamente attivo; un composto meso è una singola molecola, non una miscela."},
{id:"C109",s:"chem",u:7,q:"Un composto meso:",o:["ha centri stereogenici ma un piano di simmetria interno ed è inattivo","ha centri stereogenici, nessun piano di simmetria ed è otticamente attivo","è una miscela equimolare di due enantiomeri, otticamente inattiva","non ha centri stereogenici ed è quindi otticamente inattivo","ha un solo centro stereogenico e un piano di simmetria"],e:"Esempio: l'acido meso-tartarico. È achirale nonostante abbia due carboni stereogenici.",h:"Pensa all'acido meso-tartarico: due centri stereogenici, ma la molecola è simmetrica.",x:"Senza piano di simmetria la molecola sarebbe chirale e attiva; la miscela equimolare è il racemo; un meso ha almeno due centri stereogenici."},
{id:"C110",s:"chem",u:7,q:"Quanti stereoisomeri sono possibili al massimo per una molecola con 3 centri stereogenici?",o:["8","3","6","9","4"],e:"Al massimo 2ⁿ = 2³ = 8 (meno se esistono forme meso).",h:"Numero massimo di stereoisomeri = 2ⁿ, con n centri stereogenici.",x:"3, 6 e 9 non sono potenze di 2; 4 corrisponde a 2 centri."},
{id:"C111",s:"chem",u:7,q:"Il 2-butene presenta isomeria cis/trans perché:",o:["ciascun carbonio del doppio legame porta due sostituenti diversi","uno dei carboni del doppio legame porta due sostituenti uguali","possiede un carbonio chirale ibridato sp³","il doppio legame si trova in posizione terminale","la rotazione attorno al doppio legame è libera"],e:"Il 1-butene non presenta isomeria geometrica perché il C1 porta due H identici.",h:"Il doppio legame non ruota; perché esistano due isomeri ogni carbonio del doppio legame deve avere due gruppi diversi.",x:"Due sostituenti uguali sullo stesso carbonio impediscono l'isomeria cis/trans; il 2-butene non ha carboni chirali; il doppio legame è interno; la rotazione attorno al doppio legame è bloccata."},
{id:"C112",s:"chem",u:7,q:"La formazione di un tioestere come l'acetil-CoA è importante in biochimica perché:",o:["è un legame 'ad alta energia', facile da trasferire nelle acilazioni","è un legame inerte che protegge il gruppo acetile dall'idrolisi","è un legame a bassa energia, stabile e difficile da idrolizzare","forma legami a idrogeno molto forti con gli enzimi","è un acido forte che cede protoni nel ciclo di Krebs"],e:"L'idrolisi dei tioesteri ha un ΔG° molto negativo; l'acetil-CoA cede il gruppo acetile nel ciclo di Krebs e nelle sintesi.",h:"I tioesteri sono legami 'attivati': la loro idrolisi ha ΔG° molto negativo.",x:"L'acetil-CoA è un donatore di gruppi acetile, quindi il legame non è inerte né a bassa energia; non è un acido forte; i legami a idrogeno non spiegano il suo ruolo."},
{id:"C113",s:"chem",u:7,q:"L'ubichinone (coenzima Q) nella catena respiratoria:",o:["trasporta elettroni passando dalla forma chinonica all'ubichinolo","trasporta elettroni legato a un gruppo eme, come il citocromo c","cede gli elettroni direttamente all'ossigeno, come il complesso IV","sintetizza ATP direttamente ruotando come la subunità F₀","è un trasportatore idrosolubile dello spazio intermembrana"],e:"L'ubichinone è un trasportatore liposolubile della membrana mitocondriale interna; accetta due elettroni e due protoni diventando ubichinolo.",h:"È un trasportatore liposolubile che si muove nella membrana mitocondriale interna e accetta 2 elettroni e 2 protoni.",x:"Il citocromo c ha un eme ed è idrosolubile; è il complesso IV a cedere elettroni all'O₂; l'ATP sintasi produce ATP; l'ubichinone sta nella membrana, non nello spazio intermembrana."},
{id:"C114",s:"chem",u:7,q:"La decarbossilazione è particolarmente facile per:",o:["i β-chetoacidi","gli alcani","gli eteri","le ammine terziarie","gli alcoli primari"],e:"I β-chetoacidi (es. acetoacetato) perdono CO₂ già per blando riscaldamento tramite uno stato di transizione ciclico.",h:"La perdita di CO₂ è facilitata se c'è un carbonile in posizione β rispetto al carbossile (stato di transizione ciclico).",x:"Alcani, eteri, ammine e alcoli non hanno un gruppo carbossilico da perdere come CO₂."},

{id:"C115",s:"chem",u:8,q:"A pH fisiologico (circa 7,4), un amminoacido neutro come l'alanina si trova prevalentemente come:",o:["zwitterione (−NH₃⁺ e −COO⁻)","molecola completamente neutra senza cariche","catione","anione con −NH₂ e −COO⁻","forma non ionizzata insolubile"],e:"Il gruppo carbossilico (pKa ≈ 2) è deprotonato e l'amminico (pKa ≈ 9-10) è protonato.",h:"A pH 7,4 il carbossile (pKa ≈ 2) è deprotonato e il gruppo amminico (pKa ≈ 9-10) è protonato.",x:"A pH 7,4 entrambi i gruppi sono ionizzati, quindi la molecola non è priva di cariche; con una carica + e una − non è un catione né un anione; gli amminoacidi sono solubili in acqua."},
{id:"C116",s:"chem",u:8,q:"Il punto isoelettrico di un amminoacido è il pH al quale:",o:["la carica netta della molecola è zero","l'amminoacido è completamente protonato","l'amminoacido precipita sempre","la solubilità è massima","il gruppo amminico perde il protone"],e:"Per un amminoacido con catena laterale non ionizzabile pI = (pKa₁ + pKa₂)/2. Al pI la molecola non migra in un campo elettrico.",h:"Al punto isoelettrico le cariche positive e negative della molecola si bilanciano.",x:"Completamente protonato è un catione; al pI la solubilità è minima (non massima), ma non sempre precipita; la perdita del protone amminico avviene a pH alti."},
{id:"C117",s:"chem",u:8,q:"Gli amminoacidi delle proteine umane (tranne la glicina) hanno configurazione:",o:["L","D","sia D che L in parti uguali","R per tutti","meso"],e:"La glicina (R = H) è l'unico amminoacido achirale. In convenzione R/S, quasi tutti gli L-amminoacidi sono S (la L-cisteina è R).",h:"È la stessa serie della L-gliceraldeide nella convenzione di Fischer.",x:"Le proteine non contengono D-amminoacidi in quantità significative; R/S non coincide con D/L (la cisteina è R); 'meso' riguarda molecole con più centri chirali."},
{id:"C118",s:"chem",u:8,q:"Quale dei seguenti amminoacidi ha una catena laterale carica positivamente a pH fisiologico?",o:["Lisina","Acido glutammico","Serina","Leucina","Fenilalanina"],e:"Basici: lisina, arginina (e in parte istidina). Acidi: aspartato e glutammato. Serina è polare neutra, leucina e fenilalanina idrofobiche.",h:"Basici: lisina, arginina, istidina; a pH 7,4 hanno un gruppo amminico in più protonato.",x:"Il glutammato ha una catena carica negativamente; serina è polare neutra; leucina e fenilalanina sono idrofobiche."},
{id:"C119",s:"chem",u:8,q:"Il legame peptidico:",o:["è planare per il parziale carattere di doppio legame C−N","ruota liberamente perché è un legame semplice C−N","è planare perché il legame C−N è un vero doppio legame","si forma tra due gruppi carbossilici con perdita d'acqua","è di norma in configurazione cis, non trans"],e:"La rotazione è possibile solo attorno ai legami Cα−N (φ) e Cα−C (ψ); il gruppo peptidico è di norma in configurazione trans.",h:"Il doppietto dell'azoto si delocalizza sul carbonile: il legame C−N ha un parziale carattere di doppio legame.",x:"Non ruota liberamente (non è un semplice legame singolo) ma non è nemmeno un vero doppio legame; si forma tra un carbossile e un gruppo amminico; di norma è trans."},
{id:"C120",s:"chem",u:8,q:"La struttura quaternaria di una proteina descrive:",o:["l'associazione di più catene polipeptidiche (subunità)","la sequenza lineare degli amminoacidi nella catena","le α-eliche e i foglietti β stabilizzati da legami H","il ripiegamento tridimensionale di una singola catena","i ponti disolfuro all'interno di una stessa catena"],e:"Esempio: l'emoglobina è un tetramero α₂β₂.",h:"Pensa all'emoglobina, formata da 4 catene.",x:"La sequenza è la struttura primaria; α-eliche e foglietti β sono la secondaria; il ripiegamento di una singola catena (con i suoi ponti disolfuro) è la terziaria."},
{id:"C121",s:"chem",u:8,q:"Il glucosio e il galattosio sono:",o:["epimeri in C4","enantiomeri","anomeri","isomeri di posizione del gruppo carbonilico","epimeri in C2"],e:"Differiscono solo per la configurazione al C4. Glucosio e mannosio sono epimeri in C2; glucosio e fruttosio sono isomeri costituzionali (aldoso/chetoso).",h:"Glucosio e galattosio differiscono per la configurazione di un solo carbonio chirale.",x:"Non sono speculari (non enantiomeri); gli anomeri differiscono al C1; hanno entrambi il carbonile in C1; la coppia epimera in C2 è glucosio-mannosio."},
{id:"C122",s:"chem",u:8,q:"L'α-D-glucopiranosio e il β-D-glucopiranosio sono:",o:["anomeri, che differiscono per la configurazione del C1","enantiomeri, immagini speculari non sovrapponibili","epimeri in C4, come glucosio e galattosio","epimeri in C2, come glucosio e mannosio","tautomeri, che differiscono per la posizione di un H"],e:"In soluzione si interconvertono passando per la forma aperta (mutarotazione).",h:"α e β si riferiscono alla posizione dell'OH sul carbonio che era il carbonile (anomerico).",x:"Non sono speculari (solo un centro diverso); gli epimeri in C4 e C2 sono altre coppie di zuccheri; i tautomeri differiscono per la posizione di un H."},
{id:"C123",s:"chem",u:8,q:"Il saccarosio è formato da:",o:["glucosio e fruttosio uniti da un legame α(1→2)β","due molecole di glucosio con legame α(1→4)","galattosio e glucosio con legame β(1→4)","glucosio e fruttosio uniti da un legame β(1→4)","due molecole di glucosio con legame α(1→1)"],e:"Coinvolgendo entrambi i carboni anomerici, il saccarosio non è uno zucchero riducente. Il lattosio è galattosio-β(1→4)-glucosio; il maltosio è glucosio-α(1→4)-glucosio.",h:"Il saccarosio è lo zucchero da tavola: un aldoso e un chetoso uniti tramite entrambi i carboni anomerici.",x:"Due glucosi α(1→4) danno il maltosio; galattosio + glucosio β(1→4) il lattosio; α(1→1) il trealosio. Il legame del saccarosio coinvolge il C2 del fruttosio."},
{id:"C124",s:"chem",u:8,q:"La cellulosa differisce dall'amido perché:",o:["le unità di glucosio sono unite da legami β(1→4) invece che α(1→4)","le unità di glucosio sono unite da legami α(1→6) invece che α(1→4)","è formata da fruttosio invece che da glucosio","è ramificata ogni 8-12 residui con legami β(1→6)","è un eteropolisaccaride di glucosio e galattosio"],e:"I legami β danno catene lineari rigide unite da legami a idrogeno; l'uomo non possiede enzimi per idrolizzarli.",h:"Amido e cellulosa sono entrambi fatti di glucosio: cambia la configurazione del legame tra le unità.",x:"Le ramificazioni α(1→6) sono dell'amilopectina; entrambi sono fatti di glucosio, non di fruttosio o galattosio; la cellulosa è lineare, non ramificata."},
{id:"C125",s:"chem",u:8,q:"Il glicogeno è:",o:["un polimero di glucosio con legami α(1→4) e frequenti ramificazioni α(1→6)","un polimero di glucosio con legami β(1→4) e rare ramificazioni β(1→6)","un polimero lineare di glucosio con soli legami α(1→4)","un eteropolisaccaride della matrice extracellulare","un polimero di fruttosio con legami β(2→1)"],e:"È la riserva di glucosio nel fegato e nel muscolo; è più ramificato dell'amilopectina.",h:"È la riserva di glucosio animale, simile all'amilopectina ma ancora più ramificata.",x:"I legami β(1→4) sono della cellulosa; il glicogeno è ramificato, non lineare; è un omopolisaccaride di glucosio, non di fruttosio né un componente della matrice."},
{id:"C126",s:"chem",u:8,q:"La reazione di Maillard avviene tra:",o:["il carbonile di uno zucchero riducente e un gruppo amminico libero","il carbonile di uno zucchero non riducente e un gruppo ossidrilico","il gruppo carbossilico di un acido grasso e un gruppo amminico","due zuccheri riducenti, con formazione di un legame glicosidico","un gruppo amminico e un gruppo fosfato di un nucleotide"],e:"Si forma una base di Schiff che riarrangia nel prodotto di Amadori. L'emoglobina glicata (HbA1c), usata nel monitoraggio del diabete, è un prodotto di Amadori.",h:"È la reazione che fa imbrunire gli alimenti cotti e che forma l'HbA1c: uno zucchero con un gruppo libero reagisce con un'ammina.",x:"Uno zucchero non riducente non ha un carbonile libero; il carbossile degli acidi grassi non partecipa; tra due zuccheri si forma un legame glicosidico, non una base di Schiff; il fosfato non è coinvolto."},
{id:"C127",s:"chem",u:8,q:"Un acido grasso saturo:",o:["non contiene doppi legami C=C nella catena","contiene almeno un doppio legame cis","contiene solo doppi legami in configurazione trans","è liquido a temperatura ambiente","ha una catena ramificata con un anello"],e:"Le catene sature si impacchettano bene e hanno punti di fusione più alti; i doppi legami cis creano pieghe che abbassano il punto di fusione.",h:"'Saturo' = la catena contiene il massimo numero di idrogeni possibile.",x:"Doppi legami cis o trans rendono un acido grasso insaturo; i saturi sono solidi a temperatura ambiente (burro); le catene degli acidi grassi sono di solito lineari."},
{id:"C128",s:"chem",u:8,q:"Gli acidi grassi essenziali per l'uomo sono:",o:["l'acido linoleico (ω-6) e l'acido α-linolenico (ω-3)","l'acido palmitico (16:0) e l'acido stearico (18:0)","l'acido oleico (ω-9) e l'acido palmitoleico (ω-7)","l'acido oleico (ω-9) e l'acido linoleico (ω-6)","l'acido butirrico (4:0) e l'acido arachidico (20:0)"],e:"L'uomo non sa introdurre doppi legami oltre il C9 contando dal carbossile, quindi deve assumerli con la dieta.",h:"Sono polinsaturi con doppi legami oltre il C9: l'uomo non sa introdurli, quindi vanno assunti con la dieta.",x:"Palmitico, stearico, butirrico e arachidico sono saturi e sintetizzabili; oleico e palmitoleico sono monoinsaturi sintetizzabili dall'organismo."},
{id:"C129",s:"chem",u:8,q:"I trigliceridi sono:",o:["esteri del glicerolo con tre acidi grassi","esteri del glicerolo con due acidi grassi e un fosfato","ammidi della sfingosina con un acido grasso","esteri del colesterolo con un acido grasso","esteri di un alcol a lunga catena con un acido grasso"],e:"Sono la principale riserva energetica (tessuto adiposo) e sono molecole apolari.",h:"'Tri-gliceridi': glicerolo con tutti e tre gli ossidrili esterificati.",x:"Con un fosfato al posto di un acido grasso si ha un fosfolipide; la sfingosina è lo scheletro degli sfingolipidi; gli esteri del colesterolo e le cere sono altre classi."},
{id:"C130",s:"chem",u:8,q:"I glicerofosfolipidi, come la fosfatidilcolina:",o:["anfipatici: testa polare fosforilata e due code idrofobiche","anfipatici: testa polare zuccherina e una coda idrofobica","completamente apolari, come i trigliceridi","derivati della sfingosina con una sola coda idrofobica","completamente polari e solubili in acqua in ogni rapporto"],e:"Sono i principali componenti delle membrane biologiche. Gli sfingolipidi (es. sfingomielina) hanno invece come scheletro la sfingosina.",h:"Glicerolo + 2 acidi grassi + fosfato + colina: una parte idrofila e una idrofoba.",x:"Una testa zuccherina caratterizza i glicolipidi; i fosfolipidi non sono apolari né completamente polari; la sfingosina è lo scheletro degli sfingolipidi."},
{id:"C131",s:"chem",u:8,q:"Il colesterolo:",o:["è uno sterolo a quattro anelli fusi con un OH in C3","è uno sterolo a quattro anelli fusi con un gruppo chetonico in C3","è un acido grasso insaturo a lunga catena","è un glicerofosfolipide con testa di colina","è uno sterolo idrosolubile assente nelle membrane animali"],e:"Nelle membrane ne modula la fluidità. Da esso derivano cortisolo, aldosterone, ormoni sessuali, vitamina D e acidi biliari.",h:"Il nome stesso lo indica come sterolo (suffisso '-olo': un alcol) con quattro anelli fusi.",x:"In C3 c'è un OH, non un chetone; non è un acido grasso né un fosfolipide; è insolubile in acqua ed è abbondante nelle membrane animali."},
{id:"C132",s:"chem",u:8,q:"Un nucleotide è costituito da:",o:["una base azotata, un pentoso e uno o più gruppi fosfato","una base azotata e un pentoso, senza gruppi fosfato","una base azotata, un esoso e uno o più gruppi fosfato","un pentoso e uno o più gruppi fosfato, senza base","due basi azotate unite da un ponte fosfato"],e:"Il nucleoside è base + zucchero (legame N-glicosidico); aggiungendo i fosfati sul C5' si ottiene il nucleotide.",h:"Nucleotide = nucleoside (base + zucchero) + fosfato.",x:"Senza fosfato si ha un nucleoside; lo zucchero è un pentoso (ribosio o desossiribosio), non un esoso; senza base o con due basi non è un nucleotide."},
{id:"C133",s:"chem",u:8,q:"Le basi puriniche sono:",o:["adenina e guanina","citosina, timina e uracile","adenina e citosina","guanina e timina","solo l'uracile"],e:"Le purine hanno due anelli fusi; le pirimidine (C, T, U) un solo anello.",h:"Le purine hanno due anelli fusi; le pirimidine uno solo (citosina, timina, uracile).",x:"Citosina, timina e uracile sono pirimidine: scarti ogni opzione che le contiene."},
{id:"C134",s:"chem",u:8,q:"L'energia dell'ATP disponibile per il lavoro cellulare deriva soprattutto:",o:["dall'idrolisi dei legami fosfoanidridici tra i fosfati","dall'idrolisi del legame estere tra ribosio e fosfato α","dalla rottura del legame N-glicosidico adenina-ribosio","dall'ossidazione dell'adenina a ipoxantina","dalla rottura dell'anello del ribosio"],e:"ATP + H₂O → ADP + Pi ha ΔG°' ≈ −30,5 kJ/mol, grazie alla repulsione tra cariche negative, alla stabilizzazione per risonanza e all'idratazione dei prodotti.",h:"L'energia viene dai legami tra i fosfati, che si respingono per le cariche negative.",x:"Il legame estere ribosio-fosfato α, il legame N-glicosidico e l'anello del ribosio non sono la fonte di energia sfruttata; l'adenina non viene ossidata."},
{id:"C135",s:"chem",u:8,q:"I glicosamminoglicani (es. acido ialuronico, condroitin solfato) sono:",o:["eteropolisaccaridi lineari di disaccaridi ripetuti con un amminozucchero","omopolisaccaridi ramificati di glucosio con legami α(1→4) e α(1→6)","proteine fibrose glicosilate della matrice extracellulare","eteropolisaccaridi ramificati privi di cariche negative","lipidi complessi con teste zuccherine ripetute"],e:"Sono molto carichi negativamente (carbossili e solfati), legano molta acqua e danno alla matrice extracellulare resistenza alla compressione.",h:"Sono lunghe catene non ramificate di disaccaridi ripetuti, molto cariche negativamente.",x:"Le catene ramificate di glucosio α sono glicogeno e amilopectina; non sono proteine né lipidi; sono fortemente carichi negativamente."},
{id:"C136",s:"chem",u:8,q:"I ponti disolfuro nelle proteine si formano per:",o:["ossidazione dei gruppi −SH di due residui di cisteina","riduzione dei gruppi −SH di due residui di cisteina","ossidazione dei gruppi −SCH₃ di due metionine","condensazione degli ossidrili di due serine","legame a idrogeno tra due residui di cisteina"],e:"Il legame −S−S− è covalente e stabilizza la struttura terziaria e quaternaria, ad esempio nelle catene dell'insulina e negli anticorpi.",h:"Due −SH perdono ciascuno un H formando un legame −S−S−: è un'ossidazione.",x:"La riduzione rompe i ponti disolfuro; la metionina ha zolfo ma non un −SH libero; le serine non hanno zolfo; il ponte è covalente, non un legame a idrogeno."},

/* ---------- COMPLETAMENTO ---------- */
{id:"CC01",s:"chem",u:1,q:"Il numero di Avogadro vale circa 6,02 · 10^……",c:["23"],n:23,e:"Nₐ ≈ 6,022·10²³ particelle per mole.",h:"È il numero di particelle in una mole: circa seicentomila miliardi di miliardi."},
{id:"CC02",s:"chem",u:1,q:"Il numero massimo di elettroni che può contenere un orbitale è ……",c:["2","due"],n:2,e:"Per il principio di Pauli: due elettroni con spin opposto.",h:"Per il principio di Pauli, nello stesso orbitale gli elettroni devono avere spin opposti."},
{id:"CC03",s:"chem",u:1,q:"Il numero massimo di elettroni che possono occupare gli orbitali 2p è ……",c:["6","sei"],n:6,e:"Tre orbitali p × 2 elettroni = 6.",h:"Gli orbitali p sono 3, ciascuno con al massimo 2 elettroni."},
{id:"CC04",s:"chem",u:1,q:"La regola secondo cui gli elettroni occupano singolarmente e con spin parallelo gli orbitali degeneri prima di appaiarsi è la regola di ……",c:["hund"],e:"Ad esempio l'azoto ha tre elettroni spaiati nei tre orbitali 2p.",h:"Porta il nome del fisico tedesco che la formulò; l'azoto ne è un esempio con 3 elettroni spaiati nei 2p."},
{id:"CC05",s:"chem",u:1,q:"Il numero di ossidazione del manganese nel permanganato MnO₄⁻ è ……",c:["+7","7"],n:7,e:"x + 4(−2) = −1 → x = +7.",h:"Somma dei n.o. = carica dello ione; l'ossigeno vale −2."},
{id:"CC06",s:"chem",u:1,q:"Nel metano, il carbonio presenta ibridazione ……",c:["sp3"],e:"Quattro orbitali sp³ diretti ai vertici di un tetraedro, con angoli di 109,5°.",h:"Il carbonio forma 4 legami σ uguali diretti ai vertici di un tetraedro: un orbitale s mescolato con tre p."},
{id:"CC07",s:"chem",u:1,q:"Gli elementi del gruppo 17 (F, Cl, Br, I) sono detti ……",c:["alogeni","alogeno"],e:"Hanno configurazione esterna ns² np⁵ e tendono a formare anioni con carica −1.",h:"Dal greco 'che generano sali': con i metalli formano sali come NaCl."},
{id:"CC08",s:"chem",u:1,q:"Il tempo necessario perché metà dei nuclei di un campione radioattivo decada si chiama tempo di ……",c:["dimezzamento","emivita","semivita","dimezzamento fisico"],e:"Dopo n tempi di dimezzamento resta la frazione (1/2)ⁿ.",h:"È il tempo dopo il quale resta metà dei nuclei radioattivi iniziali."},
{id:"CC09",s:"chem",u:2,q:"Lo zero assoluto corrisponde a …… °C",c:["-273","-273,15","-273.15","−273"],n:-273.15,tol:0.002,e:"0 K = −273,15 °C.",h:"T(°C) = T(K) − 273."},
{id:"CC10",s:"chem",u:2,q:"La legge PV = nRT è l'equazione di stato dei gas ……",c:["perfetti","ideali","perfetto","ideale"],e:"Con R = 0,0821 L·atm/(mol·K) = 8,314 J/(mol·K).",h:"È il gas del modello senza volume proprio delle molecole e senza attrazioni tra loro."},
{id:"CC11",s:"chem",u:2,q:"Il passaggio diretto dallo stato solido a quello aeriforme si chiama ……",c:["sublimazione"],e:"Il passaggio inverso si chiama brinamento.",h:"È il passaggio della naftalina o del ghiaccio secco a temperatura ambiente."},
{id:"CC12",s:"chem",u:2,q:"La funzione di stato che misura il grado di disordine di un sistema è l'……",c:["entropia"],e:"Nei processi spontanei l'entropia totale dell'universo aumenta.",h:"Si indica con S; nei processi spontanei quella dell'universo aumenta."},
{id:"CC13",s:"chem",u:2,q:"Una reazione con ΔG < 0 si dice ……",c:["esoergonica","spontanea"],e:"Con ΔG > 0 la reazione è endoergonica.",h:"'Eso-' significa 'verso fuori': il sistema cede energia libera."},
{id:"CC14",s:"chem",u:3,q:"Un litro di soluzione 0,5 M di glucosio contiene …… moli di glucosio.",c:["0,5","0.5"],n:0.5,e:"n = M × V = 0,5 × 1.",h:"Moli = molarità × volume (in litri)."},
{id:"CC15",s:"chem",u:3,q:"Una soluzione con la stessa pressione osmotica del plasma si dice ……",c:["isotonica","isosmotica","isotonico"],e:"Esempi: NaCl 0,9% e glucosio 5%.",h:"'Iso' = uguale, 'tonica' = tensione (pressione osmotica)."},
{id:"CC16",s:"chem",u:3,q:"Il coefficiente i che corregge le proprietà colligative per la dissociazione degli elettroliti si chiama fattore di ……",c:["van't hoff","van t hoff","vant hoff","van hoff"],e:"Per NaCl i ≈ 2, per CaCl₂ i ≈ 3, per il glucosio i = 1.",h:"Porta il nome del chimico olandese, primo premio Nobel per la chimica, che studiò la pressione osmotica."},
{id:"CC17",s:"chem",u:3,q:"Diluendo 100 mL di HCl 1 M fino a un volume finale di 1 L, la concentrazione diventa …… M",c:["0,1","0.1"],n:0.1,e:"M₁V₁ = M₂V₂: 1 × 0,1 = M₂ × 1.",h:"Diluizione: M₁·V₁ = M₂·V₂."},
{id:"CC18",s:"chem",u:3,q:"La pressione osmotica di una soluzione si calcola con la formula π = i·M·R·……",c:["t","temperatura","temperatura assoluta"],e:"T è la temperatura assoluta in kelvin (legge di van 't Hoff).",h:"Formula di van 't Hoff, analoga a PV = nRT: π = i·M·R·…"},
{id:"CC19",s:"chem",u:4,q:"L'energia minima che i reagenti devono possedere perché un urto sia efficace si chiama energia di ……",c:["attivazione"],e:"Nella teoria dello stato di transizione corrisponde all'altezza della barriera energetica.",h:"È l'altezza della 'collina' energetica da superare; i catalizzatori la abbassano."},
{id:"CC20",s:"chem",u:4,q:"Il principio secondo cui un sistema all'equilibrio perturbato reagisce in modo da opporsi alla perturbazione è il principio di ……",c:["le chatelier","le châtelier","lechatelier","le chatelier-braun","equilibrio mobile"],e:"È detto anche principio dell'equilibrio mobile.",h:"Porta il nome del chimico francese che lo enunciò nel 1884: un sistema perturbato reagisce opponendosi alla perturbazione."},
{id:"CC21",s:"chem",u:4,q:"Per l'equilibrio eterogeneo CaCO₃(s) ⇌ CaO(s) + CO₂(g), la costante Kc è uguale alla concentrazione di ……",c:["co2","anidride carbonica","diossido di carbonio","biossido di carbonio"],e:"I solidi puri non compaiono nell'espressione della costante di equilibrio.",h:"I solidi puri non compaiono nella costante: resta solo la specie gassosa."},
{id:"CC22",s:"chem",u:4,q:"Il prodotto di solubilità di un sale poco solubile si indica con il simbolo ……",c:["ks","kps","ksp"],e:"Per un sale AB, Ks = [A⁺][B⁻] in una soluzione satura.",h:"È la costante dell'equilibrio sale(s) ⇌ ioni in una soluzione satura."},
{id:"CC23",s:"chem",u:5,q:"A 25 °C il prodotto ionico dell'acqua Kw vale 1 · 10^……",c:["-14","−14"],n:-14,e:"Kw = [H₃O⁺][OH⁻] = 10⁻¹⁴, quindi pH + pOH = 14.",h:"Kw = [H₃O⁺]·[OH⁻] = 10⁻⁷ × 10⁻⁷."},
{id:"CC24",s:"chem",u:5,q:"Una soluzione con [H₃O⁺] = 10⁻⁹ M ha pH ……",c:["9","nove"],n:9,e:"pH = −log(10⁻⁹) = 9: la soluzione è basica.",h:"pH = −log[H₃O⁺]."},
{id:"CC25",s:"chem",u:5,q:"Una soluzione con pOH = 4 ha pH ……",c:["10","dieci"],n:10,e:"pH = 14 − pOH.",h:"A 25 °C pH + pOH = 14."},
{id:"CC26",s:"chem",u:5,q:"Secondo Lewis, un acido è una specie che accetta un …… elettronico.",c:["doppietto","coppia","doppietto di elettroni","doppietto elettronico"],e:"Esempi di acidi di Lewis: BF₃, Al³⁺, H⁺.",h:"Lewis ragiona in termini di coppie di elettroni: la base li dona, l'acido li accetta."},
{id:"CC27",s:"chem",u:5,q:"Un tampone formato da un acido debole con pKa = 4,8 e dalla sua base coniugata in concentrazioni uguali ha pH ……",c:["4,8","4.8"],n:4.8,e:"Con [A⁻] = [HA], log 1 = 0 e pH = pKa.",h:"Henderson-Hasselbalch con [A⁻] = [HA]: il logaritmo di 1 vale 0."},
{id:"CC28",s:"chem",u:5,q:"In una cella elettrochimica l'elettrodo dove avviene l'ossidazione si chiama ……",c:["anodo"],e:"La riduzione avviene al catodo.",h:"In ogni cella la riduzione avviene al catodo; l'ossidazione all'elettrodo opposto."},
{id:"CC29",s:"chem",u:5,q:"L'equazione che permette di calcolare il potenziale di un elettrodo in condizioni non standard è l'equazione di ……",c:["nernst"],e:"E = E° − (RT/nF)·ln Q.",h:"Porta il nome del chimico tedesco premio Nobel 1920: E = E° − (RT/nF)·ln Q."},
{id:"CC30",s:"chem",u:5,q:"Per un elettrodo standard a idrogeno il potenziale di riduzione standard vale per convenzione …… V",c:["0","zero","0,00","0.00"],n:0,e:"È il riferimento rispetto al quale si misurano tutti gli E°.",h:"È il riferimento rispetto al quale si misurano tutti gli altri potenziali standard."},
{id:"CC31",s:"chem",u:5,q:"La costante di Faraday corrisponde alla carica di una mole di ……",c:["elettroni","elettrone"],e:"F ≈ 96 485 C/mol.",h:"F ≈ 96 485 C/mol: è la carica di un numero di Avogadro di particelle cariche negativamente."},
{id:"CC32",s:"chem",u:6,q:"Il nome IUPAC dell'idrocarburo CH₃−CH₂−CH₂−CH₂−CH₃ è ……",c:["pentano","n-pentano"],e:"Cinque atomi di carbonio, catena lineare, solo legami semplici.",h:"Cinque carboni in catena lineare, solo legami semplici: prefisso 'pent-' e suffisso degli alcani."},
{id:"CC33",s:"chem",u:6,q:"Il numero di elettroni π del benzene è ……",c:["6","sei"],n:6,e:"Tre doppi legami formali delocalizzati: 4n + 2 con n = 1.",h:"Regola di Hückel con n = 1: 4n + 2."},
{id:"CC34",s:"chem",u:6,q:"Nel 3-etil-2-metilesano ci sono …… atomi di carbonio.",c:["9","nove"],n:9,e:"Esano (6) + etile (2) + metile (1) = 9.",h:"Somma i carboni della catena principale (esano) e dei sostituenti (etile e metile)."},
{id:"CC35",s:"chem",u:6,q:"Le reazioni di …… trasformano un alogenuro alchilico in un alchene con perdita di HX.",c:["eliminazione","eliminazioni","deidroalogenazione"],e:"Possono seguire un meccanismo E1 (via carbocatione) o E2 (concertato).",h:"È il contrario dell'addizione: due atomi vengono tolti da carboni adiacenti e si forma un doppio legame."},
{id:"CC36",s:"chem",u:6,q:"Il prodotto principale della sostituzione elettrofila del benzene con HNO₃ in presenza di H₂SO₄ è il ……",c:["nitrobenzene"],e:"L'elettrofilo è lo ione nitronio NO₂⁺.",h:"L'elettrofilo è lo ione nitronio NO₂⁺, che sostituisce un H dell'anello."},
{id:"CC37",s:"chem",u:7,q:"Il gruppo funzionale −SH si chiama gruppo ……",c:["tiolico","tiolo","sulfidrilico","solfidrilico","mercaptano","sulfidrile","solfidrile","tiolo (sulfidrile)"],e:"È presente nella cisteina e nel coenzima A.",h:"Dal greco 'theion', zolfo: è l'analogo solforato dell'alcol."},
{id:"CC38",s:"chem",u:7,q:"L'ossidazione di un alcol secondario produce un ……",c:["chetone"],e:"Esempio: 2-propanolo → acetone (propanone).",h:"L'alcol secondario ha il carbonio dell'OH legato a due carboni: il carbonile che si forma è interno."},
{id:"CC39",s:"chem",u:7,q:"L'idrolisi basica di un estere, usata per ottenere i saponi dai trigliceridi, si chiama ……",c:["saponificazione"],e:"Si ottengono glicerolo e i sali degli acidi grassi.",h:"Il nome deriva dal prodotto che si ottiene: il sapone."},
{id:"CC40",s:"chem",u:7,q:"Un estere ciclico intramolecolare si chiama ……",c:["lattone"],e:"Esempio: il glucono-δ-lattone.",h:"Gli esteri ciclici prendono il nome dal latte (acido lattico): …one."},
{id:"CC41",s:"chem",u:7,q:"Un atomo di carbonio legato a quattro sostituenti diversi si dice ……",c:["chirale","stereogenico","asimmetrico","stereocentro"],e:"È centro di chiralità: la molecola può esistere come coppia di enantiomeri.",h:"Dal greco 'cheir', mano: come le mani, la molecola non è sovrapponibile alla sua immagine speculare."},
{id:"CC42",s:"chem",u:7,q:"La sostanza che fa ruotare il piano della luce polarizzata in senso orario si dice ……",c:["destrogira","destrorotatoria","destrogiro"],e:"Si indica con (+); quella che ruota in senso antiorario è levogira (−).",h:"Dal latino 'dexter', destra: si indica con (+)."},
{id:"CC43",s:"chem",u:8,q:"L'unico amminoacido proteico non chirale è la ……",c:["glicina"],e:"La catena laterale della glicina è un atomo di H.",h:"È l'amminoacido più piccolo: la sua catena laterale è un solo atomo di idrogeno."},
{id:"CC44",s:"chem",u:8,q:"Il legame che unisce due amminoacidi in una proteina si chiama legame ……",c:["peptidico","ammidico"],e:"È un legame ammidico tra il carbossile di un amminoacido e l'amminico del successivo.",h:"Unisce il carbossile di un amminoacido al gruppo amminico del successivo, liberando una molecola d'acqua."},
{id:"CC45",s:"chem",u:8,q:"Il polisaccaride di riserva tipico delle cellule animali è il ……",c:["glicogeno"],e:"Nelle piante la riserva è l'amido.",h:"È ramificato e si accumula nel fegato e nei muscoli."},
{id:"CC46",s:"chem",u:8,q:"Il disaccaride del latte, formato da galattosio e glucosio, è il ……",c:["lattosio"],e:"Viene idrolizzato dall'enzima lattasi.",h:"Viene digerito dall'enzima lattasi."},
{id:"CC47",s:"chem",u:8,q:"L'acido grasso saturo con 16 atomi di carbonio si chiama acido ……",c:["palmitico","esadecanoico"],e:"Lo stearico ha 18 C; l'oleico ha 18 C e un doppio legame cis in Δ9.",h:"Prende il nome dall'olio di palma."},
{id:"CC48",s:"chem",u:8,q:"Nel DNA il pentoso presente nei nucleotidi è il ……",c:["desossiribosio","2-desossiribosio","2'-desossiribosio","deossiribosio","2-deossiribosio"],e:"Rispetto al ribosio manca l'OH in posizione 2'.",h:"È il ribosio senza l'ossidrile in posizione 2'."},
{id:"CC49",s:"chem",u:8,q:"Il numero di gruppi carbossilici liberi nel dipeptide Glu-Gly è ……",c:["2","due"],n:2,e:"Un carbossile della catena laterale del Glu più il carbossile C-terminale della Gly; il carbossile α del Glu è impegnato nel legame peptidico.",h:"Nel dipeptide il carbossile α del Glu è impegnato nel legame peptidico; conta quelli rimasti liberi."},
{id:"CC50",s:"chem",u:8,q:"La forma ciclica a sei termini del glucosio si chiama glucopiranosio; quella a cinque termini del fruttosio si chiama fruttofuranosio. In entrambi i casi l'anello si forma per reazione intramolecolare di tipo ……",c:["emiacetalico","emichetalico","emiacetale","emichetale","emiacetalica","emichetalica"],e:"Il glucosio (aldoso) forma un emiacetale, il fruttosio (chetoso) un emichetale.",h:"Un ossidrile della stessa molecola si addiziona al carbonile: è la stessa reazione aldeide + alcol."}
);
